CREATE TABLE IF NOT EXISTS "lastbench_signups" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "full_name" text NOT NULL,
  "phone" text,
  "email" text,
  "stage" text DEFAULT 'claude-design-experience' NOT NULL,
  "source" text DEFAULT 'lastbench-homepage' NOT NULL,
  "language" text DEFAULT 'en' NOT NULL,
  "contact_consent" boolean NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT "lastbench_signups_full_name_length_check"
    CHECK (char_length(btrim("full_name")) BETWEEN 2 AND 120),
  CONSTRAINT "lastbench_signups_phone_length_check"
    CHECK ("phone" IS NULL OR char_length(btrim("phone")) BETWEEN 9 AND 40),
  CONSTRAINT "lastbench_signups_email_shape_check"
    CHECK (
      "email" IS NULL
      OR (
        char_length(btrim("email")) BETWEEN 5 AND 200
        AND "email" LIKE '%@%'
      )
    ),
  CONSTRAINT "lastbench_signups_contact_required_check"
    CHECK ("phone" IS NOT NULL OR "email" IS NOT NULL),
  CONSTRAINT "lastbench_signups_stage_check"
    CHECK ("stage" = 'claude-design-experience'),
  CONSTRAINT "lastbench_signups_source_check"
    CHECK ("source" = 'lastbench-homepage'),
  CONSTRAINT "lastbench_signups_language_check"
    CHECK ("language" IN ('en', 'bn')),
  CONSTRAINT "lastbench_signups_contact_consent_check"
    CHECK ("contact_consent" = true)
);

ALTER TABLE "lastbench_signups" ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "lastbench_signups" FROM PUBLIC, anon, authenticated;
REVOKE ALL ON SEQUENCE "lastbench_signups_id_seq" FROM PUBLIC, anon, authenticated;

GRANT INSERT ON TABLE "lastbench_signups" TO anon, authenticated;
GRANT USAGE ON SEQUENCE "lastbench_signups_id_seq" TO anon, authenticated;

CREATE POLICY "public can submit last bench signup"
ON "lastbench_signups"
FOR INSERT
TO anon, authenticated
WITH CHECK (
  char_length(btrim("full_name")) BETWEEN 2 AND 120
  AND ("phone" IS NULL OR char_length(btrim("phone")) BETWEEN 9 AND 40)
  AND (
    "email" IS NULL
    OR (
      char_length(btrim("email")) BETWEEN 5 AND 200
      AND "email" LIKE '%@%'
    )
  )
  AND ("phone" IS NOT NULL OR "email" IS NOT NULL)
  AND "stage" = 'claude-design-experience'
  AND "source" = 'lastbench-homepage'
  AND "language" IN ('en', 'bn')
  AND "contact_consent" = true
);
